 def src(title,url,locator,kind='学术研究与原典书目'):
  return dict(title=title,url=url,locator=locator,kind=kind,note='本文为自编导读；原典、译者说明及现代研究分开阅读。没有收录或复制该入口的全文。')
 def sep(slug,title):return src('斯坦福哲学百科：'+title,'https://plato.stanford.edu/entries/'+slug+'/','相关著作、年代与书目')
 def text(title,url,locator):return src(title,url,locator,'原典旧英译入口')
 works=[]
